CREATE TABLE IF NOT EXISTS terminal_role_bursts (server_id BIGINT NOT NULL,player_id BIGINT NOT NULL,account_id BIGINT NOT NULL,request_id VARCHAR(128) NOT NULL,day VARCHAR(10) NOT NULL,award_points BIGINT NOT NULL,PRIMARY KEY(server_id,player_id,request_id),UNIQUE KEY terminal_role_bursts_day(server_id,player_id,day),KEY idx_terminal_role_bursts_account_id(account_id)) ENGINE=InnoDB;
